import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    // An explicitly tagged octal integer without a sign ("0o7") still matched
    // the original explicit pattern (sign was optional), resolving to 7.
    // The changed pattern requires a sign before 0o, so this now throws.
    assert.strictEqual(load('!!int "0o7"'), 7);
  });
});

